import { test } from "node:test";
import assert from "node:assert/strict";
import { applyCoupon, checkCoupon, type Coupon } from "../src/coupons.ts";
import { priceCart } from "../src/checkout.ts";
import { redeemCoupon, type RedemptionStore } from "../src/redemption.ts";
import { promoBanners } from "../src/promotions.ts";

// Every test pins "now", so results don't depend on when or where the suite runs.
const at = (iso: string) => () => new Date(iso);

const winter: Coupon = {
    code: "WINTER20",
    percentOff: 20,
    startsAt: "2020-01-01T00:00:00Z",
    expiresAt: "2020-02-01T00:00:00Z",
    maxRedemptions: null,
    redemptions: 0,
};

function memoryStore(coupons: Coupon[], conflicts = 0) {
    const rows = new Map(coupons.map((c) => [c.code, { coupon: c, version: 1 }]));
    const redemptions = new Map<string, string>();
    let conflictsLeft = conflicts;
    const store: RedemptionStore = {
        getCoupon: async (code) => rows.get(code) ?? null,
        saveCoupon: async (coupon, expectedVersion) => {
            const row = rows.get(coupon.code)!;
            if (conflictsLeft > 0) {
                conflictsLeft--;
                rows.set(coupon.code, { coupon: { ...row.coupon, redemptions: row.coupon.redemptions + 1 }, version: row.version + 1 });
                return false;
            }
            if (row.version !== expectedVersion) return false;
            rows.set(coupon.code, { coupon, version: row.version + 1 });
            return true;
        },
        findRedemption: async (code, orderId) => {
            const redeemedAt = redemptions.get(`${code}/${orderId}`);
            return redeemedAt ? { redeemedAt } : null;
        },
        addRedemption: async (code, orderId, redeemedAt) => void redemptions.set(`${code}/${orderId}`, redeemedAt),
    };
    return { store, rows, redemptions };
}

test("a coupon is valid inside its window", () => {
    const result = checkCoupon(winter, at("2020-01-15T12:00:00Z"));
    console.log("WINTER20 on 2020-01-15:", result);
    assert.deepEqual(result, { ok: true, percentOff: 20 });
});

test("a coupon is not valid before it starts, and expires exactly at expiresAt", () => {
    assert.deepEqual(checkCoupon(winter, at("2019-12-31T23:59:59Z")), { ok: false, reason: "not_started" });
    assert.deepEqual(checkCoupon(winter, at("2020-02-01T00:00:00Z")), { ok: false, reason: "expired" });
});

test("expiry follows the injected clock, not the machine's clock", () => {
    const longLived: Coupon = { ...winter, expiresAt: "2098-01-01T00:00:00Z" };
    assert.deepEqual(checkCoupon(longLived, at("2099-06-01T00:00:00Z")), { ok: false, reason: "expired" });
});

test("applyCoupon rounds the discount down, and priceCart normalises the code", async () => {
    const cart = applyCoupon(999, { ...winter, percentOff: 15 }, at("2020-01-10T00:00:00Z"));
    assert.deepEqual(cart, { subtotalCents: 999, discountCents: 149, totalCents: 850, rejected: null });
    const repo = { find: async (code: string) => (code === "WINTER20" ? winter : null) };
    const priced = await priceCart([{ sku: "mug", unitPriceCents: 1500, quantity: 2 }], " winter20 ", repo, at("2020-01-20T00:00:00Z"));
    assert.equal(priced.totalCents, 2400);
});

test("redeeming the same order twice counts once", async () => {
    const { store, rows } = memoryStore([winter]);
    const first = await redeemCoupon(store, "WINTER20", "order-1", at("2020-01-15T00:00:00Z"));
    const again = await redeemCoupon(store, "WINTER20", "order-1", at("2020-01-15T00:00:05Z"));
    assert.deepEqual(first, { ok: true, percentOff: 20, alreadyRedeemed: false });
    assert.deepEqual(again, { ok: true, percentOff: 20, alreadyRedeemed: true });
    assert.equal(rows.get("WINTER20")?.coupon.redemptions, 1);
});

test("redemption re-reads after a concurrent update and respects the limit", async () => {
    const { store, rows } = memoryStore([{ ...winter, maxRedemptions: 2 }], 1);
    assert.equal((await redeemCoupon(store, "WINTER20", "order-1", at("2020-01-15T00:00:00Z"))).ok, true);
    assert.equal(rows.get("WINTER20")?.coupon.redemptions, 2);
    assert.deepEqual(await redeemCoupon(store, "WINTER20", "order-2", at("2020-01-15T00:00:00Z")), { ok: false, reason: "exhausted" });
});

test("redemption is rejected once the coupon has expired at the injected time", async () => {
    const { store } = memoryStore([winter]);
    assert.deepEqual(await redeemCoupon(store, "WINTER20", "order-9", at("2020-03-01T00:00:00Z")), { ok: false, reason: "expired" });
    assert.deepEqual(await redeemCoupon(store, "NOPE", "order-9", at("2020-01-15T00:00:00Z")), { ok: false, reason: "unknown_code" });
});

test("homepage banners show the best active promotions at a given moment", () => {
    const coupons: Coupon[] = [
        winter,
        { ...winter, code: "VIP30", percentOff: 30 },
        { ...winter, code: "SPRING10", percentOff: 10, startsAt: "2020-03-01T00:00:00Z", expiresAt: "2020-04-01T00:00:00Z" },
        { ...winter, code: "EVERGREEN5", percentOff: 5, expiresAt: null },
    ];
    const banners = promoBanners(coupons, 2, at("2020-01-20T00:00:00Z"));
    assert.deepEqual(banners.map((b) => b.code), ["VIP30", "WINTER20"]);
    assert.deepEqual(promoBanners(coupons, 5, at("2020-03-15T00:00:00Z")).map((b) => b.code), ["SPRING10", "EVERGREEN5"]);
});
